@pytest.mark.parametrize("reenable_before_live", [True, False]) def test_nf3_disabled_interval_stays_silent_after_flip_in_global_backfill(tmp_path, ctl, reenable_before_live): env = Env(tmp_path) ctl["cu_b"]["fail"] = 30 env.start() env.step() assert env.w.backfilling and "cu_a" in env.w.phase()["evaluated"] env.start(disabled=("cu_a",)) disabled_event = env.event("cu_a") env.step() if reenable_before_live: env.start() assert env.w.backfilling and env.w.db.meta("disabled:cu_a") is None assert env.rec("cu_a") is None else: # benign control: re-enable after go-live uses the per-check path ctl["cu_b"]["fail"] = 0 env.step() assert not env.w.backfilling env.start() assert env.rec("cu_a")["state"] == "pending" env.step() actual = keys(env) print({"reenable_before_live": reenable_before_live, "disabled_event": disabled_event, "sent": actual, "phase": env.w.phase(), "catchup": env.rec("cu_a")}) > assert f"ev:{disabled_event}" not in actual, f"disabled-interval event sent on first live run: {actual}" E AssertionError: disabled-interval event sent on first live run: ['ev:1002'] E assert 'ev:1002' not in ['ev:1002']
